import java.util.Optional;
import java.util.stream.Stream;

/** Keeps countries rows in memory, for tests and for trying the services without a database. */
public class MemoryCountryRepository implements CountryRepository {
    private final Map<List<Object>, Country> rows = new LinkedHashMap<>();

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(Country row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getDocumentId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Country> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryCountryRepository::keyOf, MemoryCountryRepository::compareKeys));
    }

    @Override
    public Optional<Country> findByDocumentId(String documentId) {
        return visible().filter((row) -> Objects.equals(row.getDocumentId(), documentId)).findFirst();
    }

    @Override
    public Page<Country> list(int offset, int limit) {
        List<Country> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
