    public Optional<Country> findById(Double id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Country insert(Country entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Country update(Country entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Country entity) {
        rows.remove(keyOf(entity));
    }
}

