package app.repositories;

import app.Documents;
import app.common.Page;
import app.entities.Product;
import com.mongodb.client.model.Filters;
import com.mongodb.client.model.FindOneAndUpdateOptions;
import com.mongodb.client.model.ReturnDocument;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.WeakHashMap;
import org.bson.Document;
import org.bson.types.ObjectId;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Sort;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

/** Keeps products documents in the database, through a MongoTemplate. Every write is stored at once. */
public class MongoProductRepository implements ProductRepository {
    /** The document each entity was read from: a change writes only the fields that differ */
    private static final Map<Product, Document> LOADED = Collections.synchronizedMap(new WeakHashMap<>());

    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("sku", "title", "price", "stock", "reference", "picture", "related");

    private final MongoTemplate mongo;

    public MongoProductRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<Product> findById(String id) {
        Product found = mongo.findOne(Query.query(Criteria.where("id").is(id)), Product.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Product> list(int offset, int limit) {
        List<Product> items = mongo.find(new Query().with(Sort.by("id")).skip(offset).limit(limit), Product.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), Product.class), offset, limit);
    }

    @Override
    public Optional<Product> findBySku(String sku) {
        Product found = mongo.findOne(Query.query(Criteria.where("sku").is(sku)), Product.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public List<Product> findAllByTitle(String title) {
        return mongo.find(Query.query(Criteria.where("title").is(title)).with(Sort.by("id")), Product.class).stream().map(this::loaded).toList();
    }

    @Override
    public Product insert(Product entity) {
        if (entity.getStock() == null) entity.setStock(0.0);
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
        return loaded(entity);
    }

    @Override
    public Product update(Product entity) {
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Product.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Product entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Product.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
    }

    @Override
    public Optional<Product> addRelated(String id, String related) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        Document change = new Document("$push", new Document("related", new ObjectId(related)));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Product.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Product.class, document)));
    }

    @Override
    public Optional<Product> removeRelated(String id, String related) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        Document change = new Document("$pull", new Document("related", new ObjectId(related)));
        Document filter = new Document("_id", new ObjectId(id));
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Product.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Product", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Product.class, document)));
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
    private Product loaded(Product entity) {
        LOADED.put(entity, Documents.of(mongo, entity));
        return entity;
    }
}

