package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.entities.Country;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Operations on countries. Repositories commit every write. */
public class CountryService {
    private final UnitOfWork uow;

    public CountryService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "countries" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Country current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("documentId");
            if (value == null) {
                if (creating || values.containsKey("documentId")) errors.add(new FieldError("_id", "is required"));
            }
        }
        {
            Object value = values.get("id");
            if (value == null) {
                if (creating || values.containsKey("id")) errors.add(new FieldError("id", "is required"));
            }
        }
        {
            Object value = values.get("name");
            if (value == null) {
                if (creating || values.containsKey("name")) errors.add(new FieldError("name", "is required"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Country", errors);
    }

    /** Values that must be unique are not taken by another row. */
    private void checkUnique(UnitOfWork uow, Map<String, Object> values, Country current) {
        {
            Double id = (Double) (values.containsKey("id") ? values.get("id") : current == null ? null : current.getId());
            if (id != null) {
                Optional<Country> other = uow.countries().findById(id);
                if (other.isPresent() && (current == null || !Objects.equals(other.get().getDocumentId(), current.getDocumentId())))
                    throw new ConflictException("Country", "id is already taken", List.of("id"));
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Country current) {
        validate(uow, values, current);
        checkUnique(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Country entity, Map<String, Object> values) {
        if (values.containsKey("documentId")) entity.setDocumentId((String) values.get("documentId"));
        if (values.containsKey("id")) entity.setId((Double) values.get("id"));
        if (values.containsKey("name")) entity.setName((String) values.get("name"));
    }

    /** The Country with this key; NotFoundException when there is none. */
    private Country find(UnitOfWork uow, String documentId) {
        return uow.countries().findByDocumentId(documentId).orElseThrow(() -> new NotFoundException("Country", documentId));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(CountryChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.id() != null && changes.id().isPresent()) values.put("id", changes.id().value());
        if (changes.name() != null && changes.name().isPresent()) values.put("name", changes.name().value());
        return values;
    }

    /** Stores a new Country after checking it. */
    public Country createCountry(Country country) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (country.getDocumentId() != null) values.put("documentId", country.getDocumentId());
        if (country.getId() != null) values.put("id", country.getId());
        if (country.getName() != null) values.put("name", country.getName());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.countries().insert(country);
        });
    }

    /** The Country with this key; NotFoundException when there is none. */
    public Country getCountry(String documentId) {
        return find(uow, documentId);
    }

    /** A page of countries, by primary key. */
    public Page<Country> listCountries(int offset, int limit) {
        return uow.countries().list(offset, limit);
    }

    /** Changes the given values of a Country. */
    public Country updateCountry(String documentId, CountryChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Country current = find(uow, documentId);
            check(uow, values, current);
            apply(current, values);
            return uow.countries().update(current);
        });
    }

    /** Deletes a Country. */
    public void deleteCountry(String documentId) {
        uow.transaction((uow) -> {
            Country current = find(uow, documentId);
            uow.countries().delete(current);
            return null;
        });
    }

    /** The Country with this id, if there is one. */
    public Optional<Country> findCountryById(Double id) {
        return uow.countries().findById(id);
    }
}

