import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Operations on customers. Repositories commit every write. */
public class CustomerService {
    // TODO: passwordHash is returned with the entity; use DTOs to leave it out
    private final UnitOfWork uow;

    public CustomerService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Customer current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("email");
            if (value == null) {
                if (creating || values.containsKey("email")) errors.add(new FieldError("email", "is required"));
            } else {
                if (value instanceof String text && text.length() > 120) errors.add(new FieldError("email", "is longer than 120 characters"));
            }
        }
        {
            Object value = values.get("name");
            if (value == null) {
                if (creating || values.containsKey("name")) errors.add(new FieldError("name", "is required"));
            } else {
                if (!(String.valueOf(value).length() >= 2)) errors.add(new FieldError("name", "must have >= 2 characters"));
            }
        }
        {
            Object value = values.get("level");
            if (value != null) {
                if (!List.of("basic", "gold").contains(String.valueOf(value))) errors.add(new FieldError("level", "must be one of: basic, gold"));
            }
        }
        {
            Object value = values.get("address");
            if (value != null) {
                Customer.Address document = (Customer.Address) value;
                if (document != null) checkAddress(document, "address", errors);
            }
        }
        {
            Object value = values.get("preferences");
            if (value != null) {
                Customer.Preferences document = (Customer.Preferences) value;
                if (document != null) checkPreferences(document, "preferences", errors);
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Customer", errors);
    }

    /** Values that must be unique are not taken by another row. */
    private void checkUnique(UnitOfWork uow, Map<String, Object> values, Customer current) {
        {
            String email = (String) (values.containsKey("email") ? values.get("email") : current == null ? null : current.getEmail());
            if (email != null) {
                Optional<Customer> other = uow.customers().findByEmail(email);
                if (other.isPresent() && (current == null || !Objects.equals(other.get().getId(), current.getId())))
                    throw new ConflictException("Customer", "email is already taken", List.of("email"));
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Customer current) {
        validate(uow, values, current);
        checkUnique(uow, values, current);
    }

    /** Sets the given values on the entity. */
    @SuppressWarnings("unchecked")
    private static void apply(Customer entity, Map<String, Object> values) {
        if (values.containsKey("email")) entity.setEmail((String) values.get("email"));
        if (values.containsKey("name")) entity.setName((String) values.get("name"));
        if (values.containsKey("passwordHash")) entity.setPasswordHash((String) values.get("passwordHash"));
        if (values.containsKey("active")) entity.setActive((Boolean) values.get("active"));
        if (values.containsKey("level")) entity.setLevel((String) values.get("level"));
        if (values.containsKey("address")) entity.setAddress((Customer.Address) values.get("address"));
        if (values.containsKey("tags")) entity.setTags((List<String>) values.get("tags"));
        if (values.containsKey("preferences")) entity.setPreferences((Customer.Preferences) values.get("preferences"));
        if (values.containsKey("extra")) entity.setExtra((Object) values.get("extra"));
        if (values.containsKey("deletedAt")) entity.setDeletedAt((Instant) values.get("deletedAt"));
        if (values.containsKey("updatedAt")) entity.setUpdatedAt((Instant) values.get("updatedAt"));
    }

    /** The Customer with this key; NotFoundException when there is none. */
    private Customer find(UnitOfWork uow, String id) {
        return uow.customers().findById(id).orElseThrow(() -> new NotFoundException("Customer", id));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(CustomerChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.email() != null && changes.email().isPresent()) values.put("email", changes.email().value());
        if (changes.name() != null && changes.name().isPresent()) values.put("name", changes.name().value());
        if (changes.passwordHash() != null && changes.passwordHash().isPresent()) values.put("passwordHash", changes.passwordHash().value());
        if (changes.active() != null && changes.active().isPresent()) values.put("active", changes.active().value());
        if (changes.level() != null && changes.level().isPresent()) values.put("level", changes.level().value());
        if (changes.address() != null && changes.address().isPresent()) values.put("address", changes.address().value());
        if (changes.tags() != null && changes.tags().isPresent()) values.put("tags", changes.tags().value());
        if (changes.preferences() != null && changes.preferences().isPresent()) values.put("preferences", changes.preferences().value());
        if (changes.extra() != null && changes.extra().isPresent()) values.put("extra", changes.extra().value());
        if (changes.deletedAt() != null && changes.deletedAt().isPresent()) values.put("deletedAt", changes.deletedAt().value());
        if (changes.updatedAt() != null && changes.updatedAt().isPresent()) values.put("updatedAt", changes.updatedAt().value());
        return values;
    }

    /** What a Address does not follow of its rules, each with the path of its field. */
    private static void checkAddress(Customer.Address value, String path, List<FieldError> errors) {
        if (value.getStreet() == null) errors.add(new FieldError(path + ".street", "is required"));
        if (value.getCity() == null) errors.add(new FieldError(path + ".city", "is required"));
        if (value.getLocation() != null) checkAddressLocation(value.getLocation(), path + ".location", errors);
    }

    /** What a Location does not follow of its rules, each with the path of its field. */
    private static void checkAddressLocation(Customer.Address.Location value, String path, List<FieldError> errors) {
        if (value.getType() != null && !List.of("Point").contains(value.getType())) errors.add(new FieldError(path + ".type", "must be one of: Point"));
    }

    /** What a Preferences does not follow of its rules, each with the path of its field. */
    private static void checkPreferences(Customer.Preferences value, String path, List<FieldError> errors) {
    }

    /** Stores a new Customer after checking it. */
    public Customer createCustomer(Customer customer) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (customer.getEmail() != null) values.put("email", customer.getEmail());
        if (customer.getName() != null) values.put("name", customer.getName());
        if (customer.getPasswordHash() != null) values.put("passwordHash", customer.getPasswordHash());
        if (customer.getActive() != null) values.put("active", customer.getActive());
        if (customer.getLevel() != null) values.put("level", customer.getLevel());
        if (customer.getAddress() != null) values.put("address", customer.getAddress());
        if (customer.getTags() != null) values.put("tags", customer.getTags());
        if (customer.getPreferences() != null) values.put("preferences", customer.getPreferences());
        if (customer.getExtra() != null) values.put("extra", customer.getExtra());
        if (customer.getDeletedAt() != null) values.put("deletedAt", customer.getDeletedAt());
        if (customer.getUpdatedAt() != null) values.put("updatedAt", customer.getUpdatedAt());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.customers().insert(customer);
        });
    }

    /** The Customer with this key; NotFoundException when there is none. */
    public Customer getCustomer(String id) {
        return find(uow, id);
    }

    /** A page of customers, by primary key. */
    public Page<Customer> listCustomers(int offset, int limit) {
        return uow.customers().list(offset, limit);
    }

    /** Changes the given values of a Customer. */
    public Customer updateCustomer(String id, CustomerChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Customer current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.customers().update(current);
