package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.entities.Order;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Operations on orders. Repositories commit every write. */
public class OrderService {
    private final UnitOfWork uow;

    public OrderService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Order current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("number");
            if (value == null) {
                if (creating || values.containsKey("number")) errors.add(new FieldError("number", "is required"));
            }
        }
        {
            Object value = values.get("year");
            if (value == null) {
                if (creating || values.containsKey("year")) errors.add(new FieldError("year", "is required"));
            }
        }
        {
            Object value = values.get("customer");
            if (value == null) {
                if (creating || values.containsKey("customer")) errors.add(new FieldError("customer", "is required"));
            }
        }
        {
            Object value = values.get("lines");
            if (value == null) {
                if (creating || values.containsKey("lines")) errors.add(new FieldError("lines", "is required"));
            } else {
                @SuppressWarnings("unchecked")
                List<Order.Line> document = (List<Order.Line>) value;
                if (document != null) {
                    for (int i0 = 0; i0 < document.size(); i0++) {
                        if (document.get(i0) == null) errors.add(new FieldError("lines" + "." + i0, "is required"));
                        else checkLine(document.get(i0), "lines" + "." + i0, errors);
                    }
                }
            }
        }
        {
            Object value = values.get("notes");
            if (value != null) {
                @SuppressWarnings("unchecked")
                List<Order.Note> document = (List<Order.Note>) value;
                if (document != null) {
                    for (int i0 = 0; i0 < document.size(); i0++) {
                        if (document.get(i0) == null) errors.add(new FieldError("notes" + "." + i0, "is required"));
                        else checkNote(document.get(i0), "notes" + "." + i0, errors);
                    }
                }
            }
        }
        {
            String customer = (String) (values.containsKey("customer") ? values.get("customer") : current == null ? null : current.getCustomer());
            if (customer != null && uow.customers().findById(customer).isEmpty())
                errors.add(new FieldError("customer", "no Customer has this key"));
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Order", errors);
    }

    /** Values that must be unique are not taken by another row. */
    private void checkUnique(UnitOfWork uow, Map<String, Object> values, Order current) {
        {
            Double year = (Double) (values.containsKey("year") ? values.get("year") : current == null ? null : current.getYear());
            Double number = (Double) (values.containsKey("number") ? values.get("number") : current == null ? null : current.getNumber());
            if (year != null && number != null) {
                Optional<Order> other = uow.orders().findByYearAndNumber(year, number);
                if (other.isPresent() && (current == null || !Objects.equals(other.get().getId(), current.getId())))
                    throw new ConflictException("Order", "year, number is already taken", List.of("year", "number"));
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Order current) {
        validate(uow, values, current);
        checkUnique(uow, values, current);
    }

    /** Sets the given values on the entity. */
    @SuppressWarnings("unchecked")
    private static void apply(Order entity, Map<String, Object> values) {
        if (values.containsKey("number")) entity.setNumber((Double) values.get("number"));
        if (values.containsKey("year")) entity.setYear((Double) values.get("year"));
        if (values.containsKey("customer")) entity.setCustomer((String) values.get("customer"));
        if (values.containsKey("lines")) entity.setLines((List<Order.Line>) values.get("lines"));
        if (values.containsKey("notes")) entity.setNotes((List<Order.Note>) values.get("notes"));
    }

    /** The Order with this key; NotFoundException when there is none. */
    private Order find(UnitOfWork uow, String id) {
        return uow.orders().findById(id).orElseThrow(() -> new NotFoundException("Order", id));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(OrderChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.number() != null && changes.number().isPresent()) values.put("number", changes.number().value());
        if (changes.year() != null && changes.year().isPresent()) values.put("year", changes.year().value());
        if (changes.customer() != null && changes.customer().isPresent()) values.put("customer", changes.customer().value());
        if (changes.lines() != null && changes.lines().isPresent()) values.put("lines", changes.lines().value());
        if (changes.notes() != null && changes.notes().isPresent()) values.put("notes", changes.notes().value());
        return values;
    }

    /** What a Line does not follow of its rules, each with the path of its field. */
    private static void checkLine(Order.Line value, String path, List<FieldError> errors) {
        if (value.getProduct() == null) errors.add(new FieldError(path + ".product", "is required"));
        if (value.getQuantity() == null) errors.add(new FieldError(path + ".quantity", "is required"));
        if (value.getQuantity() != null && !(new BigDecimal(String.valueOf(value.getQuantity())).compareTo(new BigDecimal("1")) >= 0)) errors.add(new FieldError(path + ".quantity", "must be >= 1"));
        if (value.getPrice() == null) errors.add(new FieldError(path + ".price", "is required"));
        if (value.getStatus() != null && !List.of("pending", "sent").contains(value.getStatus())) errors.add(new FieldError(path + ".status", "must be one of: pending, sent"));
    }

    /** What a Note does not follow of its rules, each with the path of its field. */
    private static void checkNote(Order.Note value, String path, List<FieldError> errors) {
    }

    /** Stores a new Order after checking it. */
    public Order createOrder(Order order) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (order.getNumber() != null) values.put("number", order.getNumber());
        if (order.getYear() != null) values.put("year", order.getYear());
        if (order.getCustomer() != null) values.put("customer", order.getCustomer());
        if (order.getLines() != null) values.put("lines", order.getLines());
        if (order.getNotes() != null) values.put("notes", order.getNotes());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.orders().insert(order);
        });
    }

    /** The Order with this key; NotFoundException when there is none. */
    public Order getOrder(String id) {
        return find(uow, id);
    }

    /** A page of orders, by primary key. */
    public Page<Order> listOrders(int offset, int limit) {
        return uow.orders().list(offset, limit);
    }

    /** Changes the given values of a Order. */
    public Order updateOrder(String id, OrderChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Order current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.orders().update(current);
        });
    }

    /** Deletes a Order. */
    public void deleteOrder(String id) {
        uow.transaction((uow) -> {
            Order current = find(uow, id);
            uow.orders().delete(current);
            return null;
        });
    }

    /** The Order with this year and number, if there is one. */
    public Optional<Order> findOrderByYearAndNumber(Double year, Double number) {
        return uow.orders().findByYearAndNumber(year, number);
    }

    /** The orders with this customer. */
    public List<Order> listOrdersByCustomer(String customer) {
        return uow.orders().listByCustomer(customer);
    }

    /** Adds an item to lines. */
    public Order addLine(String id, Order.Line line) {
        List<FieldError> errors = new ArrayList<>();
        checkLine(line, "lines", errors);
        if (!errors.isEmpty()) throw new ValidationFailedException("Order", errors);
        return uow.transaction((uow) -> {
            find(uow, id);
            return uow.orders().addLine(id, line).orElseThrow(() -> new NotFoundException("Order", id));
        });
    }

    /** Removes an item from lines, by its identifier. */
    public Order removeLine(String id, String lineId) {
        return uow.transaction((uow) -> {
            Order current = find(uow, id);
            if (current.getLines() == null || current.getLines().stream().noneMatch((item) -> lineId.equals(item.getId()))) throw new NotFoundException("Line", lineId);
            return uow.orders().removeLine(id, lineId).orElseThrow(() -> new NotFoundException("Order", id));
        });
    }

    /** Adds an item to notes. */
    public Order addNote(String id, Order.Note note) {
        List<FieldError> errors = new ArrayList<>();
        checkNote(note, "notes", errors);
        if (!errors.isEmpty()) throw new ValidationFailedException("Order", errors);
        return uow.transaction((uow) -> {
            find(uow, id);
            return uow.orders().addNote(id, note).orElseThrow(() -> new NotFoundException("Order", id));
        });
    }

    /** Removes an item from notes, by its identifier. */
    public Order removeNote(String id, String noteId) {
        return uow.transaction((uow) -> {
            Order current = find(uow, id);
            if (current.getNotes() == null || current.getNotes().stream().noneMatch((item) -> noteId.equals(item.getId()))) throw new NotFoundException("Note", noteId);
            return uow.orders().removeNote(id, noteId).orElseThrow(() -> new NotFoundException("Order", id));
        });
    }
