        @Test
        void isStoredAndReadBack() {
            Country stored = Factories.addCountry(uow, 1);
            Country found = uow.countries().findByDocumentId(stored.getDocumentId()).orElseThrow();
            assertEquals(stored.getDocumentId(), found.getDocumentId());
            assertTrue(uow.countries().findById(stored.getId()).isPresent());
        }

        @Test
        void listsRowsByKey() {
            Factories.addCountry(uow, 1);
            Factories.addCountry(uow, 2);
            var page = uow.countries().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void storesTheChanges() {
            Country stored = Factories.addCountry(uow, 1);
            stored.setName("changed");
            uow.countries().update(stored);
            assertEquals("changed", uow.countries().findByDocumentId(stored.getDocumentId()).orElseThrow().getName());
        }

        @Test
        void isDeleted() {
            Country stored = Factories.addCountry(uow, 1);
