            assertTrue(uow.countries().findByDocumentId(stored.getDocumentId()).isEmpty());
        }
    }

    @Nested
    class CountryServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            CountryService service = new CountryService(uow);
            int n = 100;
            Country row = Factories.newCountry(1);
            var created = service.createCountry(row);
            var found = service.getCountry(created.getDocumentId());
            assertEquals(created.getDocumentId(), found.getDocumentId());
        }

        @Test
        void refusesAMissingValue() {
            CountryService service = new CountryService(uow);
            int n = 100;
            Country row = Factories.newCountry(1);
            row.setDocumentId(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createCountry(row));
            assertEquals(List.of("_id"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesARepeatedUniqueValue() {
            CountryService service = new CountryService(uow);
            int n = 100;
            Country row = Factories.newCountry(1);
