            var created = service.createCountry(row);
            service.updateCountry(created.getDocumentId(), new CountryChanges(Patch.of(created.getId()), Patch.absent()));
        }

        @Test
        void saysWhenARowIsMissing() {
            CountryService service = new CountryService(uow);
            assertThrows(NotFoundException.class, () -> service.getCountry("missing"));
        }

        @Test
        void changesARow() {
            CountryService service = new CountryService(uow);
            int n = 100;
            Country row = Factories.newCountry(1);
            var created = service.createCountry(row);
            var updated = service.updateCountry(created.getDocumentId(), new CountryChanges(Patch.absent(), Patch.of("changed")));
            assertEquals("changed", updated.getName());
